import{_ as s,o as n,c as t,a2 as e}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"04c · B 片即梦执行表（开盖片 v1）","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/04c-b-jimeng-v1.md","filePath":"lab/shuangyu-fries/04c-b-jimeng-v1.md","lastUpdated":1786871523000}'),p={name:"lab/shuangyu-fries/04c-b-jimeng-v1.md"};function o(l,a,i,r,d,c){return n(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="_04c-·-b-片即梦执行表-开盖片-v1" tabindex="-1">04c · B 片即梦执行表（开盖片 v1） <a class="header-anchor" href="#_04c-·-b-片即梦执行表-开盖片-v1" aria-label="Permalink to &quot;04c · B 片即梦执行表（开盖片 v1）&quot;">​</a></h1><blockquote><p>阶段 4 · 执行 ｜ 2026-08-09 ｜ <strong>内部工作文档，可直接粘贴使用</strong></p><p>B 片 = 开盖片：6–10 秒、9:16 竖屏、抖音/小红书信息流。定义见 <a href="./01-proposal">01 · 提案</a>，复用关系见 <a href="./03-storyboard#素材复用-b-片从这里剪出">03 · 分镜</a>。内容边界与红线与 A 片 <a href="./04a-jimeng-v1">04a</a> 同一套，不重复处直接引用。</p></blockquote><h2 id="镜头表-8-秒" tabindex="-1">镜头表（8 秒） <a class="header-anchor" href="#镜头表-8-秒" aria-label="Permalink to &quot;镜头表（8 秒）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>时长</th><th>画面</th><th>来源</th><th>声音</th></tr></thead><tbody><tr><td><strong>B1</strong></td><td>2s</td><td>第一帧即撕封口</td><td><strong>实拍</strong>（实物到后）；demo 用开盖视频后期占位</td><td>撕封「嘶啦」</td></tr><tr><td><strong>B2</strong></td><td>1.5s</td><td>杯口俯视露出</td><td>即梦生成，参考图 <code>stick-product.jpg</code></td><td>开盖后短安静 + 沙沙声</td></tr><tr><td><strong>B3</strong></td><td>2s</td><td>掰断、碎屑炸开</td><td>即梦生成，A 片镜头 8 的 9:16 重跑</td><td><strong>「咔嚓」主角级</strong></td></tr><tr><td><strong>B4</strong></td><td>2.5s</td><td>产品落版 + 主标题</td><td>后期合成（A 片镜头 10 流程的竖版）</td><td>收尾音</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">B 片没有铺垫</p><p>第一帧就是撕封口，<strong>不用一秒铺垫</strong>——信息流的生死在第一帧。任何「先拍个桌面再伸手」的版本都废。</p></div><hr><h2 id="b1-·-撕封口-不生成" tabindex="-1">B1 · 撕封口：不生成 <a class="header-anchor" href="#b1-·-撕封口-不生成" aria-label="Permalink to &quot;B1 · 撕封口：不生成&quot;">​</a></h2><p>理由见<a href="./01-proposal#六-制作方式说明">提案第六节</a>：真实手部 + 不可逆形变 + 真实包装文字，生成必然画错，且这一镜是 B 片第一帧，错不起。</p><p><strong>实拍清单</strong>（实物到后可发客户代拍，或我方拍）：</p><ul><li>9:16 竖屏，1080p 起，手机支架固定——开盖视频最大的问题是手持晃动；</li><li>光线充足：窗边日光或台灯侧上方打光，<strong>避开开盖视频那种偏暗环境</strong>；</li><li>背景干净纯色台面；</li><li>首帧手指已捏住封口拉沿，一次连贯撕开，2–3 秒；</li><li><strong>保留封口内侧的调味粉</strong>（开盖视频里证实存在的真实细节）；</li><li>撕完把杯口转向镜头停 1 秒——可兼作 B2 的实拍备选；</li><li>不配日式配乐、不给日文副标特写（<a href="./02-materials">决议 ③</a>）。</li></ul><p><strong>demo 占位</strong>：开盖视频取 4.5–7.5s 撕封段，稳定 + 调色 + 9:16 裁切。交付时注明占位，正式版须实拍。</p><hr><h2 id="b2-·-杯口俯视露出" tabindex="-1">B2 · 杯口俯视露出 <a class="header-anchor" href="#b2-·-杯口俯视露出" aria-label="Permalink to &quot;B2 · 杯口俯视露出&quot;">​</a></h2><p><strong>图像 · 首帧</strong>｜参考图 <code>stick-product.jpg</code>（主体参考）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>俯视直下视角看进一个已开盖的零食杯口，银色卷边一圈，</span></span>
<span class="line"><span>杯内装满浅金色薯条脆，表面带红色调味颗粒，干爽哑光无油光，</span></span>
<span class="line"><span>杯身外壁只露出纯色、无任何图案文字，背景为深色木桌，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端食品广告微距摄影，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>俯拍，微距，浅景深 f/2.2，</span></span>
<span class="line"><span>柔和顶光 + 侧面一盏硬光勾边，</span></span>
<span class="line"><span>9:16，高细节</span></span></code></pre></div><p><strong>视频 · 图生视频</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>镜头从正上方极缓慢推近杯口，杯中薯条脆逐渐充满画面，</span></span>
<span class="line"><span>杯口边缘有几粒碎屑。慢动作。</span></span>
<span class="line"><span>画面中不出现任何文字、logo、包装图案。</span></span></code></pre></div><p><strong>验收</strong>：杯口只有银色卷边与产品，<strong>杯身不得出现任何印刷</strong>；出现假包装即废。</p><hr><h2 id="b3-·-掰断-a-片镜头-8-的-9-16-重跑" tabindex="-1">B3 · 掰断（A 片镜头 8 的 9:16 重跑） <a class="header-anchor" href="#b3-·-掰断-a-片镜头-8-的-9-16-重跑" aria-label="Permalink to &quot;B3 · 掰断（A 片镜头 8 的 9:16 重跑）&quot;">​</a></h2><p>首尾帧 Prompt 用 <a href="./04a-jimeng-v1#镜头-8-掰断瞬间-首尾帧">04a 镜头 8</a> 原文，仅改三处：</p><ol><li><code>16:9</code> → <code>9:16</code>；</li><li>构图改竖版：薯条脆与断口置于<strong>画面中上三分之一</strong>（下三分之一留给字幕与账号信息区）；</li><li>参考图同 <code>stick-product.jpg</code>。</li></ol><p><strong>视频 · 首尾帧</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>手指用力，薯条脆断裂，断口处细小碎屑向四周飞散。</span></span>
<span class="line"><span>高速摄影般的慢动作，断裂瞬间清晰可见。</span></span>
<span class="line"><span>镜头固定。画面中不出现任何文字、logo。</span></span></code></pre></div><p><strong>验收</strong>：同 A 片——先有断面多孔、再有碎屑；手部畸形即改跑无人版本。</p><hr><h2 id="b4-·-落版-不生成主体" tabindex="-1">B4 · 落版（不生成主体） <a class="header-anchor" href="#b4-·-落版-不生成主体" aria-label="Permalink to &quot;B4 · 落版（不生成主体）&quot;">​</a></h2><p>流程同 <a href="./04a-jimeng-v1#镜头-10-产品出镜-不生成主体">04a 镜头 10</a>，竖版差异：</p><ul><li>背景 Prompt 的 <code>16:9</code> → <code>9:16</code>，构图改为<strong>产品位在中下、上方留空给主标题</strong>；</li><li>包装用 <code>render-cup.jpg</code> 去背合成，光效对照 <code>cup-front.jpg</code>；正面平视，不突出日文副标；</li><li>主标题「原薯鲜切」+ 片尾 logo（<code>logo.jpg</code> 去背，® 待确认）。</li></ul><p><strong>图像 · 背景</strong>｜无参考图</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纯净的深色石质台面，背景为柔和的暖调渐变，</span></span>
<span class="line"><span>台面光斑与景深虚化集中在画面下半部，上半部留空，</span></span>
<span class="line"><span>无任何物体，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高端食品广告微距摄影，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感，</span></span>
<span class="line"><span></span></span>
<span class="line"><span>中景，浅景深，平视，</span></span>
<span class="line"><span>影棚布光，主光从左上方 45 度，右侧柔光补光，背景轻微渐变压暗，</span></span>
<span class="line"><span>9:16，高细节</span></span></code></pre></div><hr><h2 id="音效是主角" tabindex="-1">音效是主角 <a class="header-anchor" href="#音效是主角" aria-label="Permalink to &quot;音效是主角&quot;">​</a></h2><p>B 片无人声，情绪全在音效。<strong>全部后期拟音，不依赖生成视频自带声音</strong>：</p><table tabindex="0"><thead><tr><th>时点</th><th>音效</th></tr></thead><tbody><tr><td>B1 撕封</td><td>铝箔「嘶啦」，干脆、一次完成</td></tr><tr><td>B1→B2 之间</td><td><strong>半拍安静</strong>——开盖瞬间的信息量靠安静衬出来</td></tr><tr><td>B3 掰断</td><td>高频清脆「咔嚓」，全片最响</td></tr><tr><td>B4 落版</td><td>轻收尾音，不抢字幕</td></tr></tbody></table><h2 id="固定负面词" tabindex="-1">固定负面词 <a class="header-anchor" href="#固定负面词" aria-label="Permalink to &quot;固定负面词&quot;">​</a></h2><p>与 A 片相同，全量粘贴进「不希望出现的内容」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>深褐色，焦黑，油腻反光，表面浮油，</span></span>
<span class="line"><span>文字，logo，品牌标识，包装袋，包装盒，商标，日文，中文字符，</span></span>
<span class="line"><span>卡通，3D渲染感，塑料感，畸变，多余的手指，水印</span></span></code></pre></div><h2 id="生成日志" tabindex="-1">生成日志 <a class="header-anchor" href="#生成日志" aria-label="Permalink to &quot;生成日志&quot;">​</a></h2><p>每镜跑了几条、采用哪条、废的为什么废，<strong>当场记进 <a href="./05-genlog">05 · 生成日志</a></strong>。</p><hr><p><strong>上一步</strong> ← <a href="./04a-jimeng-v1">04a · 即梦执行表</a> ｜ <strong>下一步</strong> → <a href="./04d-b-gemini-v1">04d · B 片 Gemini 执行表</a></p>`,42)])])}const b=s(p,[["render",o]]);export{g as __pageData,b as default};
